    Map<String, String> properties = Maps.newHashMap();
    properties.put(HttpClientProperties.URLCONNECTION_SOCKET_TIMEOUT_MS, "90");
    properties.put(HttpClientProperties.URLCONNECTION_CONNECTION_TIMEOUT_MS, "80");
    properties.put(HttpClientProperties.APACHE_SOCKET_TIMEOUT_MS, "100");
    properties.put(HttpClientProperties.APACHE_CONNECTION_TIMEOUT_MS, "200");
    properties.put(HttpClientProperties.PROXY_ENDPOINT, "http://proxy:8080");
    UrlConnectionHttpClientConfigurations urlConnectionHttpClientConfigurations = UrlConnectionHttpClientConfigurations.create(properties);
    UrlConnectionHttpClient.Builder urlConnectionHttpClientBuilder = UrlConnectionHttpClient.builder();
    UrlConnectionHttpClient.Builder spyUrlConnectionHttpClientBuilder = Mockito.spy(urlConnectionHttpClientBuilder);
    urlConnectionHttpClientConfigurations.configureUrlConnectionHttpClientBuilder(spyUrlConnectionHttpClientBuilder);
    Mockito.verify(spyUrlConnectionHttpClientBuilder).socketTimeout(Duration.ofMillis(90));
    Mockito.verify(spyUrlConnectionHttpClientBuilder).connectionTimeout(Duration.ofMillis(80));
    Mockito.verify(spyUrlConnectionHttpClientBuilder).proxyConfiguration(Mockito.any(software.amazon.awssdk.http.urlconnection.ProxyConfiguration.class));
}

