@BeforeEach
public void before() {
    this.catalog = new BigQueryMetastoreCatalog();
    this.catalog.setConf(new Configuration());
    String warehouseLocation = tempFolder.toPath().resolve("hive-warehouse").toString();
    catalog.initialize("CATALOG_ID", ImmutableMap.of(PROJECT_ID, GCP_PROJECT, CatalogProperties.WAREHOUSE_LOCATION, warehouseLocation, CatalogProperties.FILE_IO_IMPL, "org.apache.iceberg.hadoop.HadoopFileIO"), GCP_PROJECT, GCP_REGION, client);
    this.tableOps = (BigQueryTableOperations) catalog.newTableOps(IDENTIFIER);
}

@Test
public void fetchLatestMetadataFromBigQuery() throws Exception {
    Table createdTable = createTestTable();
    reset(client);
    when(client.load(TABLE_REFERENCE)).thenReturn(createdTable);
    tableOps.refresh();
    assertThat(createdTable.getExternalCatalogTableOptions().getParameters().getOrDefault(METADATA_LOCATION_PROP, "")).isEqualTo(tableOps.currentMetadataLocation());
    reset(client);
    when(client.load(TABLE_REFERENCE)).thenThrow(new NoSuchTableException("error message getTable"));
    // Refresh fails when table is not found but metadata already presents.
    assertThatThrownBy(() -> tableOps.refresh()).isInstanceOf(NoSuchTableException.class).hasMessageContaining("error message getTable");
}

