@Test
void close() {
    Map<String, String> catalogProperties = Map.of();
    SessionCatalog.SessionContext context = new SessionCatalog.SessionContext("test", "test", Map.of(OAuth2Properties.TOKEN, "context-token"), Map.of());
    Map<String, String> tableProperties = Map.of(OAuth2Properties.TOKEN, "table-token");
    TableIdentifier table = TableIdentifier.of("ns", "tbl");
    try (OAuth2Manager manager = new OAuth2Manager("test") {

        @Override
        protected AuthSessionCache newSessionCache(String name, Map<String, String> properties) {
            return new AuthSessionCache(Duration.ofHours(1), Runnable::run, Ticker.systemTicker());
        }

        @Override
        protected OAuth2Util.AuthSession newSessionFromAccessToken(String token, Map<String, String> properties, OAuth2Util.AuthSession parent) {
            return Mockito.spy(super.newSessionFromAccessToken(token, properties, parent));
        }
    };
        OAuth2Util.AuthSession catalogSession = manager.catalogSession(client, catalogProperties);
        OAuth2Util.AuthSession contextualSession = manager.contextualSession(context, catalogSession);
        OAuth2Util.AuthSession tableSession = manager.tableSession(table, tableProperties, contextualSession)) {
        manager.close();
        assertThat(manager).extracting("sessionCache").as("should close session cache").isNull();
        // all cached sessions should be closed
        Mockito.verify(contextualSession).close();
        Mockito.verify(tableSession).close();
    }
    Mockito.verify(client).withAuthSession(any());
    Mockito.verifyNoMoreInteractions(client);
}

