@ParameterizedTest
@ValueSource(strings = { "v1/oauth/tokens", "https://auth-server.com/token" })
public void testCatalogTokenRefreshFailsAndUsesCredentialForRefresh(String oauth2ServerUri) {
    Map<String, String> emptyHeaders = ImmutableMap.of();
    Map<String, String> catalogHeaders = ImmutableMap.of("Authorization", "Bearer client-credentials-token:sub=catalog");
    String credential = "catalog:secret";
    Map<String, String> basicHeaders = OAuth2Util.basicAuthHeaders(credential);
    RESTCatalogAdapter adapter = Mockito.spy(new RESTCatalogAdapter(backendCatalog));
    Answer<OAuthTokenResponse> addOneSecondExpiration = invocation -> {
        OAuthTokenResponse response = (OAuthTokenResponse) invocation.callRealMethod();
        return OAuthTokenResponse.builder().withToken(response.token()).withTokenType(response.tokenType()).withIssuedTokenType(response.issuedTokenType()).addScopes(response.scopes()).setExpirationInSeconds(1).build();
    };
    Mockito.doAnswer(addOneSecondExpiration).when(adapter).postForm(eq(oauth2ServerUri), anyMap(), eq(OAuthTokenResponse.class), anyMap(), any());
    Map<String, String> firstRefreshRequest = ImmutableMap.of("grant_type", "urn:ietf:params:oauth:grant-type:token-exchange", "subject_token", "client-credentials-token:sub=catalog", "subject_token_type", "urn:ietf:params:oauth:token-type:access_token", "scope", "catalog");
    // simulate that the token expired when it was about to be refreshed
    Mockito.doThrow(new RuntimeException("token expired")).when(adapter).postForm(eq(oauth2ServerUri), argThat(firstRefreshRequest::equals), eq(OAuthTokenResponse.class), eq(catalogHeaders), any());
    Map<String, String> contextCredentials = ImmutableMap.of();
    SessionCatalog.SessionContext context = new SessionCatalog.SessionContext(UUID.randomUUID().toString(), "user", contextCredentials, ImmutableMap.of());
    // lower retries
    AuthSessionUtil.setTokenRefreshNumRetries(1);
    RESTCatalog catalog = new RESTCatalog(context, (config) -> adapter);
    catalog.initialize("prod", ImmutableMap.of(CatalogProperties.URI, "ignored", "credential", credential, OAuth2Properties.OAUTH2_SERVER_URI, oauth2ServerUri));
    Awaitility.await().atMost(5, TimeUnit.SECONDS).untilAsserted(() -> {
        // use the exchanged catalog token
        assertThat(catalog.tableExists(TBL)).isFalse();
        // call client credentials with no initial auth
        Map<String, String> clientCredentialsRequest = ImmutableMap.of("grant_type", "client_credentials", "client_id", "catalog", "client_secret", "secret", "scope", "catalog");
        Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.POST, oauth2ServerUri, emptyHeaders, Map.of(), clientCredentialsRequest), eq(OAuthTokenResponse.class), any(), any());
        // use the client credential token for config
        Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.GET, ResourcePaths.config(), catalogHeaders), eq(ConfigResponse.class), any(), any());
        // verify the first token exchange - since an exception is thrown, we're performing
        // retries
        Mockito.verify(adapter, times(2)).postForm(eq(oauth2ServerUri), argThat(firstRefreshRequest::equals), eq(OAuthTokenResponse.class), eq(catalogHeaders), any());
        // here we make sure that the basic auth header is used after token refresh retries
        // failed
        Mockito.verify(adapter).postForm(eq(oauth2ServerUri), argThat(firstRefreshRequest::equals), eq(OAuthTokenResponse.class), eq(basicHeaders), any());
        // use the refreshed context token for table existence check
        Map<String, String> refreshedCatalogHeader = ImmutableMap.of("Authorization", "Bearer token-exchange-token:sub=client-credentials-token:sub=catalog");
        Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.HEAD, RESOURCE_PATHS.table(TBL), refreshedCatalogHeader), any(), any(), any());
    });
}

