@ParameterizedTest
@ValueSource(ints = { 21, 30 })
public void testPaginationForListNamespaces(int numberOfItems) {
    RESTCatalogAdapter adapter = Mockito.spy(new RESTCatalogAdapter(backendCatalog));
    RESTCatalog catalog = new RESTCatalog(SessionCatalog.SessionContext.createEmpty(), (config) -> adapter);
    catalog.initialize("test", ImmutableMap.of(RESTCatalogProperties.PAGE_SIZE, "10"));
    String namespaceName = "newdb";
    // create several namespaces for listing and verify
    for (int i = 0; i < numberOfItems; i++) {
        String nameSpaceName = namespaceName + i;
        catalog.createNamespace(Namespace.of(nameSpaceName));
    }
    assertThat(catalog.listNamespaces()).hasSize(numberOfItems);
    Mockito.verify(adapter).execute(reqMatcher(HTTPMethod.GET, ResourcePaths.config(), Map.of(), Map.of()), eq(ConfigResponse.class), any(), any());
    Mockito.verify(adapter, times(numberOfItems)).execute(reqMatcher(HTTPMethod.POST, RESOURCE_PATHS.namespaces(), Map.of(), Map.of()), eq(CreateNamespaceResponse.class), any(), any());
    // verify initial request with empty pageToken
    Mockito.verify(adapter).handleRequest(eq(Route.LIST_NAMESPACES), eq(ImmutableMap.of("pageToken", "", "pageSize", "10")), any(), eq(ListNamespacesResponse.class), any());
    // verify second request with updated pageToken
    Mockito.verify(adapter).handleRequest(eq(Route.LIST_NAMESPACES), eq(ImmutableMap.of("pageToken", "10", "pageSize", "10")), any(), eq(ListNamespacesResponse.class), any());
    // verify third request with update pageToken
    Mockito.verify(adapter).handleRequest(eq(Route.LIST_NAMESPACES), eq(ImmutableMap.of("pageToken", "20", "pageSize", "10")), any(), eq(ListNamespacesResponse.class), any());
}

