@Test
public void testCleanupUncommitedFilesForCleanableFailures() {
    RESTCatalogAdapter adapter = Mockito.spy(new RESTCatalogAdapter(backendCatalog));
    RESTCatalog catalog = catalog(adapter);
    if (requiresNamespaceCreate()) {
        catalog.createNamespace(TABLE.namespace());
    }
    catalog.createTable(TABLE, SCHEMA);
    DataFile file = DataFiles.builder(PartitionSpec.unpartitioned()).withPath("/path/to/data-a.parquet").withFileSizeInBytes(10).withRecordCount(2).build();
    Table table = catalog.loadTable(TABLE);
    Mockito.doThrow(new NotAuthorizedException("not authorized")).when(adapter).execute(reqMatcher(HTTPMethod.POST), any(), any(), any());
    assertThatThrownBy(() -> catalog.loadTable(TABLE).newFastAppend().appendFile(file).commit()).isInstanceOf(NotAuthorizedException.class).hasMessage("not authorized");
    // Extract the UpdateTableRequest to determine the path of the manifest list that should be
    // cleaned up
    assertThat(allRequests(adapter)).anySatisfy(req -> {
        assertThat(req.method()).isEqualTo(HTTPMethod.POST);
        assertThat(req.path()).isEqualTo(RESOURCE_PATHS.table(TABLE));
        assertThat(req.body()).isInstanceOf(UpdateTableRequest.class);
        UpdateTableRequest body = (UpdateTableRequest) req.body();
        MetadataUpdate.AddSnapshot addSnapshot = (MetadataUpdate.AddSnapshot) body.updates().get(0);
        assertThatThrownBy(() -> table.io().newInputFile(addSnapshot.snapshot().manifestListLocation())).isInstanceOf(NotFoundException.class).hasMessageContaining("No in-memory file found");
    });
}

