    assertThat(assertRefSnapshotID.snapshotId()).isEqualTo(snapshotId);
    assertThat(assertRefSnapshotID.refName()).isEqualTo(refName);
    requirements = UpdateRequirements.forUpdateTable(metadata, ImmutableList.of(new MetadataUpdate.RemoveSnapshots(Set.of(0L))));
    requirements.forEach(req -> req.validate(metadata));
    assertThat(requirements).hasSize(1).hasOnlyElementsOfTypes(UpdateRequirement.AssertTableUUID.class);
    assertTableUUID(requirements);
}

