@Test
public void testMultipleAlterTableForNoLock() throws Exception {
    Table table = catalog.loadTable(TABLE_IDENTIFIER);
    table.updateProperties().set(TableProperties.HIVE_LOCK_ENABLED, "false").commit();
    spyOps.refresh();
    TableMetadata metadataV3 = spyOps.current();
    AtomicReference<Throwable> alterTableException = new AtomicReference<>(null);
    doAnswer(i -> {
        try {
            // mock a situation where alter table is unexpectedly invoked more than once
            i.callRealMethod();
            return i.callRealMethod();
        } catch (Throwable e) {
            alterTableException.compareAndSet(null, e);
            throw e;
        }
    }).when(spyClient).alter_table_with_environmentContext(anyString(), anyString(), any(), any());
    spyOps.commit(metadataV3, metadataV1);
    verify(spyClient, times(1)).alter_table_with_environmentContext(anyString(), anyString(), any(), any());
    assertThat(alterTableException).as("Expecting to trigger an exception indicating table has been modified").hasValueMatching(t -> t.getMessage().contains("The table has been modified. The parameter value for key '"));
}

