private UUID coordinatorTest(List<DataFile> dataFiles, List<DeleteFile> deleteFiles, OffsetDateTime ts) {
    when(config.commitIntervalMs()).thenReturn(0);
    when(config.commitTimeoutMs()).thenReturn(Integer.MAX_VALUE);
    SinkTaskContext context = mock(SinkTaskContext.class);
    Coordinator coordinator = new Coordinator(catalog, config, ImmutableList.of(), clientFactory, context);
    coordinator.start();
    // init consumer after subscribe()
    initConsumer();
    coordinator.process();
    assertThat(producer.transactionCommitted()).isTrue();
    assertThat(producer.history()).hasSize(1);
    byte[] bytes = producer.history().get(0).value();
    Event commitRequest = AvroUtil.decode(bytes);
    assertThat(commitRequest.type()).isEqualTo(PayloadType.START_COMMIT);
    UUID commitId = ((StartCommit) commitRequest.payload()).commitId();
    Event commitResponse = new Event(config.connectGroupId(), new DataWritten(StructType.of(), commitId, new TableReference("catalog", ImmutableList.of("db"), "tbl"), dataFiles, deleteFiles));
    bytes = AvroUtil.encode(commitResponse);
    consumer.addRecord(new ConsumerRecord<>(CTL_TOPIC_NAME, 0, 1, "key", bytes));
    Event commitReady = new Event(config.connectGroupId(), new DataComplete(commitId, ImmutableList.of(new TopicPartitionOffset("topic", 1, 1L, ts))));
    bytes = AvroUtil.encode(commitReady);
    consumer.addRecord(new ConsumerRecord<>(CTL_TOPIC_NAME, 0, 2, "key", bytes));
    when(config.commitIntervalMs()).thenReturn(0);
    coordinator.process();
    return commitId;
}

@Test
public void testRun() {
    Coordinator coordinator = mock(Coordinator.class);
    CoordinatorThread coordinatorThread = new CoordinatorThread(coordinator);
    coordinatorThread.start();
    verify(coordinator, timeout(1000)).start();
    verify(coordinator, timeout(1000).atLeast(1)).process();
    verify(coordinator, times(0)).stop();
    assertThat(coordinatorThread.isTerminated()).isFalse();
    coordinatorThread.terminate();
    verify(coordinator, timeout(1000)).stop();
    assertThat(coordinatorThread.isTerminated()).isTrue();
}

