@TestTemplate
public void testDefaultToHadoopListing() {
    assumeThat(usePrefixListing).as("This test verifies default listing behavior and does not require prefix listing to be enabled.").isEqualTo(false);
    Table table = TABLES.create(SCHEMA, PartitionSpec.unpartitioned(), properties, tableLocation);
    List<ThreeColumnRecord> records = Lists.newArrayList(new ThreeColumnRecord(1, "AAAAAAAAAA", "AAAA"));
    Dataset<Row> df = spark.createDataFrame(records, ThreeColumnRecord.class).coalesce(1);
    df.select("c1", "c2", "c3").write().format("iceberg").mode("append").save(tableLocation);
    DeleteOrphanFilesSparkAction deleteOrphanFilesSparkAction = SparkActions.get().deleteOrphanFiles(table);
    DeleteOrphanFilesSparkAction spyAction = Mockito.spy(deleteOrphanFilesSparkAction);
    try (MockedStatic<FileSystemWalker> mockedStatic = Mockito.mockStatic(FileSystemWalker.class)) {
        spyAction.execute();
        mockedStatic.verify(() -> FileSystemWalker.listDirRecursivelyWithHadoop(anyString(), anyMap(), any(Predicate.class), any(Configuration.class), anyInt(), anyInt(), any(), any()));
    }
}

@TestTemplate
public void testSingleCommitWithRewriteFailure() {
    Table table = createTable(20);
    int fileSize = averageFileSize(table);
    List<Object[]> originalData = currentData();
    RewriteDataFilesSparkAction realRewrite = basicRewrite(table).option(RewriteDataFiles.MAX_FILE_GROUP_SIZE_BYTES, Integer.toString(fileSize * 2 + 1000));
    RewriteDataFilesSparkAction spyRewrite = Mockito.spy(realRewrite);
    // Fail groups 1, 3, and 7 during rewrite
    GroupInfoMatcher failGroup = new GroupInfoMatcher(1, 3, 7);
    doThrow(new RuntimeException("Rewrite Failed")).when(spyRewrite).rewriteFiles(any(), argThat(failGroup));
    assertThatThrownBy(spyRewrite::execute).isInstanceOf(RuntimeException.class).hasMessage("Rewrite Failed");
    table.refresh();
    List<Object[]> postRewriteData = currentData();
    assertEquals("We shouldn't have changed the data", originalData, postRewriteData);
    shouldHaveSnapshots(table, 1);
    shouldHaveNoOrphans(table);
    shouldHaveACleanCache(table);
}

